<?php
declare(strict_types=1);
require __DIR__ . '/../app/bootstrap.php';
require __DIR__ . '/../app/Layout.php';
require_role('supply','approver','admin');
$type=(string)($_GET['type']??'receipts');if(!in_array($type,['receipts','issues'],true)){http_response_code(400);exit('ประเภทรายงานไม่ถูกต้อง');}
$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['from']??''))?$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',(string)($_GET['to']??''))?$_GET['to']:'';$material=(int)($_GET['material_id']??0);$requester=(int)($_GET['requester_id']??0);$group=(int)($_GET['group_id']??0);$where=[];$params=[];
if($type==='receipts'){$where[]="sm.quantity_delta>0 AND sm.movement_type IN('opening','receipt','return_good','count_adjustment','reversal')";if($from){$where[]='DATE(sm.created_at)>=?';$params[]=$from;}if($to){$where[]='DATE(sm.created_at)<=?';$params[]=$to;}if($material){$where[]='sm.material_id=?';$params[]=$material;}$sql='SELECT sm.created_at,sm.movement_type,sm.quantity_delta,sm.reference_no,sm.reason,m.code,m.name,m.unit,u.full_name,rc.source FROM stock_movements sm JOIN materials m ON m.id=sm.material_id JOIN users u ON u.id=sm.created_by LEFT JOIN receipts rc ON sm.reference_type="receipt" AND rc.id=sm.reference_id WHERE '.implode(' AND ',$where).' ORDER BY sm.created_at,sm.id';$title='รายงานการเพิ่มวัสดุเข้าคลัง';$headers=['วันที่','รหัส/วัสดุ','ประเภท','จำนวนเพิ่ม','แหล่งที่มา/เหตุผล','อ้างอิง','ผู้บันทึก'];}
else{if($from){$where[]='DATE(i.issued_at)>=?';$params[]=$from;}if($to){$where[]='DATE(i.issued_at)<=?';$params[]=$to;}if($material){$where[]='ri.material_id=?';$params[]=$material;}if($requester){$where[]='r.requester_id=?';$params[]=$requester;}if($group){$where[]='r.work_group_id=?';$params[]=$group;}$sql='SELECT i.issued_at,i.issue_no,i.receiver_name,r.request_no,u.full_name requester,g.name group_name,m.code,m.name,m.unit,ri.requested_qty,ri.approved_qty,ii.quantity,s.full_name issued_by FROM issue_items ii JOIN issues i ON i.id=ii.issue_id JOIN requisition_items ri ON ri.id=ii.requisition_item_id JOIN requisitions r ON r.id=ri.requisition_id JOIN users u ON u.id=r.requester_id LEFT JOIN work_groups g ON g.id=r.work_group_id JOIN materials m ON m.id=ri.material_id JOIN users s ON s.id=i.issued_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY i.issued_at,i.id';$title='รายงานการเบิกและจ่ายวัสดุ';$headers=['วันที่','เลขคำขอ/ใบจ่าย','ผู้เบิก/กลุ่มงาน','รหัส/วัสดุ','ขอ','อนุมัติ','จ่ายครั้งนี้','ผู้จ่าย/ผู้รับ'];}
$stmt=db()->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();$orientation=setting('report_orientation','landscape');$headerText=setting('report_header_text','');$footerText=setting('report_footer_text','');$showLogo=setting('report_show_logo','1')==='1'&&setting('logo_path','')!=='';render_header($title,false);?><link rel="stylesheet" href="assets/report.css"><style>@media print{@page{size:A4 <?=h($orientation)?>;margin:8mm}}</style>
<main class="print-sheet report-sheet orientation-<?=h($orientation)?>"><div class="print-actions"><button class="btn primary" onclick="window.print()">พิมพ์ / บันทึก PDF</button><button class="btn secondary" onclick="window.close()">ปิด</button></div><?php if($showLogo):?><div class="report-logo-wrap"><?=brand_logo('report-logo')?></div><?php endif;?><h1><?=h($title)?></h1><h2><?=h(setting('office_name',cfg('app.office_name')))?></h2><?php if($headerText!==''):?><p class="report-custom-header"><?=h($headerText)?></p><?php endif;?><p class="report-period">ช่วงวันที่ <?=h($from?:'ทั้งหมด')?> ถึง <?=h($to?:'ทั้งหมด')?> · ออกรายงาน <?=thai_date(date('Y-m-d H:i:s'))?></p><div class="table-wrap"><table><thead><tr><?php foreach($headers as$header):?><th><?=h($header)?></th><?php endforeach;?></tr></thead><tbody>
<?php if($type==='receipts'):foreach($rows as$row):?><tr><td><?=thai_date($row['created_at'])?></td><td><?=h($row['code'].' · '.$row['name'])?><br><small><?=h($row['unit'])?></small></td><td><?=h($row['movement_type'])?></td><td><?=qty($row['quantity_delta']).' '.h($row['unit'])?></td><td><?=h($row['source']?:$row['reason'])?></td><td><?=h($row['reference_no'])?></td><td><?=h($row['full_name'])?></td></tr><?php endforeach;else:foreach($rows as$row):?><tr><td><?=thai_date($row['issued_at'])?></td><td><?=h($row['request_no'])?><br><small><?=h($row['issue_no'])?></small></td><td><?=h($row['requester'])?><br><small><?=h($row['group_name'])?></small></td><td><?=h($row['code'].' · '.$row['name'])?><br><small><?=h($row['unit'])?></small></td><td><?=qty($row['requested_qty'])?></td><td><?=qty($row['approved_qty'])?></td><td><?=qty($row['quantity']).' '.h($row['unit'])?></td><td><?=h($row['issued_by'])?><br><small>ผู้รับ: <?=h($row['receiver_name'])?></small></td></tr><?php endforeach;endif;?>
<?php if(!$rows):?><tr><td colspan="8" class="empty">ไม่พบข้อมูลตามตัวกรอง</td></tr><?php endif;?></tbody></table></div><p><b>จำนวนรายการ:</b> <?=count($rows)?></p><div class="report-sign"><div>ลงชื่อ ____________________ <?=h(setting('report_prepared_label','ผู้จัดทำ'))?><br>วันที่ ____/____/____</div><div>ลงชื่อ ____________________ <?=h(setting('report_checked_label','ผู้ตรวจสอบ'))?><br>วันที่ ____/____/____</div></div><?php if($footerText!==''):?><p class="report-custom-footer"><?=h($footerText)?></p><?php endif;?></main><?php render_footer();
